Lemma rFP_same stX stY a : s_regions stY = s_regions stX -> rFP stX a -> rFP stY a.
Proof. try hcb. try hsb. intros E. apply rFP_mono. intros rid r Hr. exists r. rewrite E. repeat split; auto; lia. Qed.

Lemma rFP_below stX a : rregions_wf stX -> rFP stX a -> a < bv_unsigned sp /\ ~ (RAUXV_CELL <= a < RAUXV_CELL + 8).
Proof. try hcb. try hsb.
  intros (_ & WR & _) [[X|[X|[X|(rid & r & Hr & K & X)]]]|X]; rewrite ?TP in X; hcb; unfold RAUXV_CELL, RLIBC, RCTX, RAM_STACK, Malloc.alloc_ceiling, Decode.alloc_ceiling in *;
    rewrite ?unsigned_lit in X by lia; [lia| lia| lia| |].
  - destruct (WR _ _ Hr) as (_ & _ & _ & RBC & RF). destruct (rreserved_disjoint _ _ RF) as (D1 & _ & D23 & D2). pose proof (lr_lo_ge r). hcb; unfold Malloc.alloc_ceiling, Decode.alloc_ceiling in RBC. lia.
  - pose proof (rfresh_image st a X (amp_reserved st AMP)). pose proof (rfresh_below st a X (amp_reserved st AMP)). destruct X as [C _]. hcb; unfold Malloc.alloc_ceiling, Decode.alloc_ceiling in C. lia.
Qed.

Lemma rerrno_not_amfp stX a : rregions_wf stX -> ram_fp stX lo (bv_unsigned sp) a -> ~ (errno_addr tp <= a < errno_addr tp + 4).
Proof. try hcb. try hsb. intros WF X. rewrite TP. eapply ram_fp_not_errno; [exact X| exact WF| exact LO]. Qed.

